from pathlib import Path
import base64
import gzip
import subprocess

root = Path("app")
PAYLOAD = """"""
patch = gzip.decompress(base64.b64decode(PAYLOAD))
subprocess.run(["patch", "-p1"], cwd=root, input=patch, check=True)

checks = {
    root / "src/game/jutsu.ts": [
        "export function specialistJutsuTraits",
        "Specialist techniques deliberately sit above ordinary elemental releases",
        "if (traits.length > 0) return j.requiresTrait",
        "if (pair) return j.requiresKekkei",
        "obsolete base-tree",
    ],
    root / "src/game/perks.ts": [
        "OBSOLETE_TREE_TECHNIQUES",
        "export function combatTechniqueIds",
        "Combat technique ${t.name}",
    ],
    root / "src/game/types.ts": [
        '"technique"',
        "techniques: string[];",
        "equipmentSpecials: string[];",
    ],
    root / "src/game/equipment.ts": [
        "export function activeEquipmentAbilities",
        "u.equipmentSpecials = abilities.map",
    ],
    root / "src/game/battle.ts": [
        'case "technique":',
        "combatTechniqueIds(n)",
        "u.equipmentSpecials?.includes(jutsuId)",
    ],
    root / "src/components/BattleScreen.tsx": [
        "COMBAT TECHNIQUES",
        "EQUIPPED GEAR TECHNIQUES",
        'setTechniqueOpen(true)',
        'setGearOpen(true)',
    ],
    root / "src/components/JutsuTree.tsx": [
        "ONE DEFINING JUTSU STYLE",
        "baseNatures.map",
        "specialistJutsuTraits(n)",
    ],
    root / "src/components/PerkTree.tsx": [
        "SKILL DEVELOPMENT TREE",
        "COMBAT TECHNIQUE",
    ],
    root / "public/sw.js": [
        "shadow-village-depth-v1-jutsu-potential-v16-specialist-combat-rework",
    ],
}
for path, needles in checks.items():
    text = path.read_text(encoding="utf-8")
    for needle in needles:
        if needle not in text:
            raise SystemExit(f"v16 validation failed: {needle} missing from {path}")

# The old one-button special architecture must not remain as a selectable BAction.
if 'case "special":' in (root / "src/game/battle.ts").read_text(encoding="utf-8"):
    raise SystemExit("v16 validation failed: old single-special battle action still present")
if '{ id: "special"' in (root / "src/components/BattleScreen.tsx").read_text(encoding="utf-8"):
    raise SystemExit("v16 validation failed: old single-special battle button still present")

print("Village depth v16 specialist identity, power-budget and combat submenu rework applied")
